<?php
namespace Tests\Feature;use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class CompanyJobTest extends TestCase{use RefreshDatabase;public function test_company_creates_quality_scored_job_from_valid_quote():void{$user=User::factory()->create(['account_type'=>'company']);$this->actingAs($user,'sanctum')->getJson('/api/v1/company/profile');$quote=$this->actingAs($user,'sanctum')->postJson('/api/v1/company/quotations',['vacancies'=>1,'duration'=>30,'applications'=>'50','urgency'=>'normal','visibility'=>'normal','classification'=>'manual','diffusion'=>[]])->json('data.reference');$response=$this->actingAs($user,'sanctum')->postJson('/api/v1/company/jobs',$this->payload($quote));$response->assertCreated()->assertJsonPath('data.status','draft')->assertJsonPath('data.quality_score',100);$id=$response->json('data.id');$this->actingAs($user,'sanctum')->postJson('/api/v1/company/jobs/'.$id.'/submit')->assertOk()->assertJsonPath('data.status','pending_payment');}public function test_company_cannot_use_another_company_quote():void{$first=User::factory()->create(['account_type'=>'company']);$second=User::factory()->create(['account_type'=>'company']);$this->actingAs($first,'sanctum')->getJson('/api/v1/company/profile');$this->actingAs($second,'sanctum')->getJson('/api/v1/company/profile');$quote=$this->actingAs($first,'sanctum')->postJson('/api/v1/company/quotations',['vacancies'=>1,'duration'=>30,'applications'=>'50','urgency'=>'normal','visibility'=>'normal','classification'=>'manual','diffusion'=>[]])->json('data.reference');$this->actingAs($second,'sanctum')->postJson('/api/v1/company/jobs',$this->payload($quote))->assertUnprocessable();}private function payload(string $quote):array{return ['quotation_reference'=>$quote,'title'=>'Desarrollador Backend Laravel','summary'=>'Buscamos una persona para ampliar nuestro equipo de desarrollo.','description'=>str_repeat('Participará en el diseño y construcción de servicios confiables para nuestros productos digitales. ',3),'requirements'=>['Experiencia con PHP','Conocimiento de Laravel','Manejo de PostgreSQL'],'benefits'=>['Seguro médico','Horario flexible'],'location'=>'Santo Domingo','modality'=>'Híbrido','contract_type'=>'Tiempo completo','salary_min'=>80000,'salary_max'=>110000,'currency'=>'DOP'];}}
